# us-intl: the console keymap for XKB's English (US, intl., with dead keys), us(intl). Arch only: swaydesk-desktop
# installs it in /usr/share/kbd/keymaps/xkb, where systemd-localed and Calamares look for a keymap converted from
# an XKB layout ("<layout>-<variant>") before their table. The table gives us-acentos, which has the dead keys
# (' then c is ç) but no AltGr layer, so ç typed with AltGr+, in the session didn't exist at the TTY.
# kbd's us-acentos as it is (plain, Shift, Ctrl and Alt layers, compose), plus AltGr and Shift+AltGr from
# xkeyboard-config's us(intl). Its dead keys the console doesn't have (double acute, macron, horn, ogonek,
# breve, ring, dot below, stroke, dot above, caron, hook) are left empty. tests/test_console_keymap.py checks it.
include "/usr/share/kbd/keymaps/i386/qwerty/us-acentos.map.gz"
keymaps 3
	altgr	keycode  41 = U+0060
	shift	altgr	keycode  41 = U+007e
	altgr	keycode   2 = U+00a1
	shift	altgr	keycode   2 = U+00b9
	altgr	keycode   3 = U+00b2
	shift	altgr	keycode   3 = VoidSymbol
	altgr	keycode   4 = U+00b3
	shift	altgr	keycode   4 = VoidSymbol
	altgr	keycode   5 = U+00a4
	shift	altgr	keycode   5 = U+00a3
	altgr	keycode   6 = U+20ac
	shift	altgr	keycode   6 = dead_cedilla
	altgr	keycode   7 = U+00bc
